func run<T>(_ operation: () async throws -> T) async throws -> T {
    var attempt = 0
    while true {
        do {
            return try await operation()
        } catch where attempt < maxRetries {
            attempt += 1
            try await Task.sleep(for: delay(forAttempt: attempt))
        }
    }
}

