import Foundation

struct CSVExporter {
    func write(_ rows: [ReportRow], to url: URL) throws {
        let csv = try export(rows)
        do {
            try csv.write(to: url, atomically: true, encoding: .utf8)
        } catch {
            throw ExportError.writeFailed(url, underlying: error)
        }
    }
